css:
.sl-gallery-3d-stage { padding-block: clamp(3rem, 6vw, 5.5rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); overflow-x: clip; }
.sl-gallery-3d-stage .sl-container { max-width: 1140px; width: 100%; margin-inline: auto; }
.sl-gallery-3d-stage .sl-header { text-align: center; margin-bottom: 3rem; }
.sl-gallery-3d-stage .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-3d-stage .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-3d-stage .sl-stage-container { position: relative; max-width: 1000px; margin-inline: auto; min-height: 380px; perspective: 1200px; display: flex; align-items: center; justify-content: center; }
.sl-gallery-3d-stage .sl-stage-container:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 6px; border-radius: var(--smartlearn-radius, 1rem); }
.sl-gallery-3d-stage .sl-stage-item { position: absolute; width: 60%; max-width: 600px; aspect-ratio: 16/9; border-radius: var(--smartlearn-radius, 1rem); overflow: hidden; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2); transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94), filter 0.4s ease; cursor: pointer; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); background-color: var(--smartlearn-card-bg); }
.sl-gallery-3d-stage .sl-stage-poster { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-3d-stage .sl-stage-center { transform: translateX(0) translateZ(0) rotateY(0); z-index: 3; filter: brightness(1); }
.sl-gallery-3d-stage .sl-stage-left { transform: translateX(-40%) translateZ(-200px) rotateY(25deg); z-index: 2; filter: brightness(0.65); }
.sl-gallery-3d-stage .sl-stage-right { transform: translateX(40%) translateZ(-200px) rotateY(-25deg); z-index: 2; filter: brightness(0.65); }
.sl-gallery-3d-stage .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 64px; height: 64px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-3d-stage .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-3d-stage .sl-play-overlay:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 3px; }
.sl-gallery-3d-stage .sl-close-video { position: absolute; top: 0.75rem; inset-inline-end: 0.75rem; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.sl-gallery-3d-stage .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-3d-stage .sl-stage-controls { display: flex; justify-content: center; gap: 0.75rem; margin-top: 1.5rem; }
.sl-gallery-3d-stage .sl-stage-nav { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.35)); background-color: var(--smartlearn-card-bg); color: var(--smartlearn-text); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.sl-gallery-3d-stage .sl-stage-nav:hover { border-color: var(--smartlearn-primary); color: var(--smartlearn-primary); }
.sl-gallery-3d-stage .sl-stage-nav:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
[dir="rtl"] .sl-gallery-3d-stage .sl-stage-nav svg { transform: scaleX(-1); }
@media (prefers-reduced-motion: reduce) {
  .sl-gallery-3d-stage .sl-stage-container { perspective: none; min-height: auto; flex-direction: column; gap: 1.5rem; }
  .sl-gallery-3d-stage .sl-stage-item { position: relative; width: 100%; transform: none; filter: none; cursor: default; transition: none; }
  .sl-gallery-3d-stage .sl-play-overlay { transition: none; }
  .sl-gallery-3d-stage .sl-stage-controls { display: none; }
}
@media (max-width: 767px) {
  .sl-gallery-3d-stage .sl-stage-container { perspective: none; min-height: auto; flex-direction: column; gap: 1rem; }
  .sl-gallery-3d-stage .sl-stage-item { position: relative; width: 100%; transform: none; filter: none; cursor: default; }
  .sl-gallery-3d-stage .sl-stage-controls { display: none; }
}

