(function() {
  function toSafeEmbedUrl(raw) {
    try {
      var u = new URL(raw, window.location.href);
      if (u.protocol !== 'https:') return '';
      var host = u.hostname.replace(/^www\./, '');
      if (host === 'youtu.be') {
        var id = u.pathname.split('/').filter(Boolean)[0];
        return id ? 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(id) + '?autoplay=1' : '';
      }
      if (host === 'youtube.com' || host === 'youtube-nocookie.com') {
        var vid = u.searchParams.get('v');
        if (!vid && u.pathname.indexOf('/embed/') === 0) vid = u.pathname.split('/')[2];
        return vid ? 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(vid) + '?autoplay=1' : '';
      }
      if (host === 'vimeo.com' || host === 'player.vimeo.com') {
        var parts = u.pathname.split('/').filter(Boolean);
        var vimeoId = parts[parts.length - 1];
        return /^\d+$/.test(vimeoId) ? 'https://player.vimeo.com/video/' + vimeoId + '?autoplay=1' : '';
      }
    } catch (e) {}
    return '';
  }
  var init = function() {
    document.querySelectorAll('.sl-gallery-3d-stage').forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var stage = root.querySelector('.sl-stage-container');
      var items = Array.prototype.slice.call(root.querySelectorAll('.sl-stage-item'));
      var prevBtn = root.querySelector('.sl-stage-prev');
      var nextBtn = root.querySelector('.sl-stage-next');
      if (!items.length) return;
      var isStacked = function() {
        return window.matchMedia('(prefers-reduced-motion: reduce)').matches || window.innerWidth < 768;
      };
      var clearVideo = function(item) {
        var oldIframe = item.querySelector('iframe');
        var oldClose = item.querySelector('.sl-close-video');
        if (oldIframe) oldIframe.remove();
        if (oldClose) oldClose.remove();
        var poster = item.querySelector('.sl-stage-poster');
        var play = item.querySelector('.sl-item-play-btn');
        if (poster) poster.style.display = '';
        if (play) play.style.display = '';
      };
      var focusItem = function(target) {
        var currentCenter = root.querySelector('.sl-stage-center') || items[0];
        if (currentCenter === target) return;
        clearVideo(currentCenter);
        var targetPos = target.classList.contains('sl-stage-left') ? 'sl-stage-left' : 'sl-stage-right';
        target.classList.remove(targetPos);
        target.classList.add('sl-stage-center');
        target.setAttribute('aria-current', 'true');
        currentCenter.classList.remove('sl-stage-center');
        currentCenter.classList.add(targetPos);
        currentCenter.removeAttribute('aria-current');
      };
      var stepStage = function(dir) {
        if (isStacked()) return;
        var centerIdx = items.findIndex(function(el) { return el.classList.contains('sl-stage-center'); });
        if (centerIdx < 0) centerIdx = 0;
        var nextIdx = (centerIdx + dir + items.length) % items.length;
        focusItem(items[nextIdx]);
      };
      items.forEach(function(item) {
        item.addEventListener('click', function() {
          if (isStacked()) return;
          focusItem(item);
        });
        var playBtn = item.querySelector('.sl-item-play-btn');
        if (!playBtn) return;
        playBtn.addEventListener('click', function(e) {
          e.stopPropagation();
          if (!isStacked() && !item.classList.contains('sl-stage-center')) {
            focusItem(item);
          }
          var safeUrl = toSafeEmbedUrl(item.getAttribute('data-video-url') || '');
          if (!safeUrl) return;
          clearVideo(item);
          var poster = item.querySelector('.sl-stage-poster');
          if (poster) poster.style.display = 'none';
          playBtn.style.display = 'none';
          var iframe = document.createElement('iframe');
          iframe.src = safeUrl;
          iframe.title = playBtn.getAttribute('aria-label') || 'Featured video';
          iframe.referrerPolicy = 'strict-origin-when-cross-origin';
          iframe.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:none;z-index:10;';
          iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
          iframe.setAttribute('allowfullscreen', 'true');
          var closeBtn = document.createElement('button');
          closeBtn.type = 'button';
          closeBtn.className = 'sl-close-video';
          closeBtn.setAttribute('aria-label', 'Close video');
          closeBtn.textContent = '×';
          closeBtn.addEventListener('click', function(ce) {
            ce.stopPropagation();
            clearVideo(item);
            playBtn.focus();
          });
          item.appendChild(iframe);
          item.appendChild(closeBtn);
          closeBtn.focus();
        });
      });
      if (prevBtn) prevBtn.addEventListener('click', function() { stepStage(-1); });
      if (nextBtn) nextBtn.addEventListener('click', function() { stepStage(1); });
      if (stage) {
        stage.addEventListener('keydown', function(e) {
          var isRtl = getComputedStyle(root).direction === 'rtl';
          if (e.key === 'ArrowLeft') { e.preventDefault(); stepStage(isRtl ? 1 : -1); }
          else if (e.key === 'ArrowRight') { e.preventDefault(); stepStage(isRtl ? -1 : 1); }
        });
      }
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
